#include "../ring3_common.hpp"
// Causeway: an append-only "why did my system change?" notebook for Davis OS.
// It records intent, expected outcome, observed outcome and recovery note as one change capsule.
static constexpr u32 W=760,H=520; static u32*pix; static u64 events,win; static bool dirty=true;
static int field=0, scroll=0; static char intent[96]={0}, expect[96]={0}, observed[96]={0}, recovery[96]={0}; static u32 il=0,el=0,ol=0,rl=0; static char logbuf[1800]={0};
static void rr(i32 x,i32 y,i32 w,i32 h,i32 r,u32 c){rect(pix,W,H,x+r,y,w-2*r,h,c);rect(pix,W,H,x,y+r,w,h-2*r,c);for(i32 yy=0;yy<r;yy++)for(i32 xx=0;xx<r;xx++){i32 dx=r-xx-1,dy=r-yy-1;if(dx*dx+dy*dy<=r*r){rect(pix,W,H,x+xx,y+yy,1,1,c);rect(pix,W,H,x+w-1-xx,y+yy,1,1,c);rect(pix,W,H,x+xx,y+h-1-yy,1,1,c);rect(pix,W,H,x+w-1-xx,y+h-1-yy,1,1,c);}}}
static u32 slen(const char*s){u32 n=0;while(s&&s[n])n++;return n;} static void copy(char*d,u32 cap,const char*s){u32 i=0;for(;s&&s[i]&&i+1<cap;i++)d[i]=s[i];d[i]=0;}
static void cat(char*d,u32 cap,const char*s){u32 n=slen(d),i=0;while(s&&s[i]&&n+1<cap)d[n++]=s[i++];d[n]=0;}
static void load(){for(u32 i=0;i<sizeof(logbuf);i++)logbuf[i]=0;i64 h=sc(32,(u64)"/Home/Documents/CAUSEWAY.LOG",1);if(h>0){i64 n=sc(33,(u64)h,(u64)logbuf,sizeof(logbuf)-1);if(n>0&&n<(i64)sizeof(logbuf))logbuf[n]=0;sc(35,(u64)h);}dirty=true;}
static void save(){if(!il)return;char line[520]={0};cat(line,sizeof(line),"CHANGE | ");cat(line,sizeof(line),intent);cat(line,sizeof(line),"\nEXPECT | ");cat(line,sizeof(line),expect);cat(line,sizeof(line),"\nOBSERVE| ");cat(line,sizeof(line),observed);cat(line,sizeof(line),"\nRECOVER| ");cat(line,sizeof(line),recovery);cat(line,sizeof(line),"\n---\n");i64 h=sc(32,(u64)"/Home/Documents/CAUSEWAY.LOG",2|4);if(h>0){sc(34,(u64)h,(u64)line,slen(line));sc(35,(u64)h);}intent[0]=expect[0]=observed[0]=recovery[0]=0;il=el=ol=rl=0;load();}
static void fieldbox(int y,const char*label,const char*v,int idx){text(pix,W,H,30,y,label,0x009aa7b2,1);rr(30,y+18,440,42,8,field==idx?0x00273542:0x001d2630);text(pix,W,H,44,y+33,v,0x00edf2f7,1);if(field==idx)rect(pix,W,H,44+(i32)slen(v)*6,y+31,2,12,0x006db6ff);}
static void draw(){fill(pix,W*H,0x0011161c);rect(pix,W,H,0,0,W,58,0x00192028);text(pix,W,H,24,18,"CAUSEWAY",0x00f3f6f9,2);text(pix,W,H,170,23,"A WHY-LEDGER FOR CHANGES",0x008d9aa6,1);fieldbox(82,"WHAT ARE YOU CHANGING?",intent,0);fieldbox(154,"WHAT SHOULD HAPPEN?",expect,1);fieldbox(226,"WHAT ACTUALLY HAPPENED?",observed,2);fieldbox(298,"HOW WOULD YOU RECOVER?",recovery,3);rr(30,384,210,42,8,0x002a6f4e);text(pix,W,H,75,399,"COMMIT CAPSULE",0x00ffffff,1);text(pix,W,H,30,452,"APPEND-ONLY: THE OLD WHY IS NEVER SILENTLY REWRITTEN",0x007f8c98,1);
rr(492,78,244,398,10,0x00192028);text(pix,W,H,510,96,"CHANGE HISTORY",0x00dfe7ee,1);text(pix,W,H,510,116,"INTENT > EXPECT > RESULT > RECOVERY",0x007f8c98,1);int y=146;char line[36];u32 li=0,skip=0;for(u32 i=0;logbuf[i]&&y<456;i++){char c=logbuf[i];if(c=='\n'){line[li]=0;if(skip++>=(u32)scroll){text(pix,W,H,510,y,line,0x00b9c5cf,1);y+=15;}li=0;}else if(li<34)line[li++]=c;}sc(SYS_PRESENT,win,(u64)pix,(u64)W*H*4);dirty=false;}
static void key(char c){char* b=field==0?intent:field==1?expect:field==2?observed:recovery;u32* n=field==0?&il:field==1?&el:field==2?&ol:&rl;if(c=='\b'){if(*n)b[--(*n)]=0;}else if(c=='\n'){field=(field+1)%4;}else if(c>=32&&c<127&&*n<94){b[(*n)++]=c;b[*n]=0;}dirty=true;}
extern "C" __attribute__((section(".text.entry"))) void _davis_start(){pix=(u32*)(u64)sc(SYS_ALLOC,(u64)W*H*4);if(!pix)sc(0,1);win=makeWindow(events,W,H,120,70);if(!win)sc(0,2);load();for(;;){Wire m{};while(sc(SYS_IPC_RECV,events,(u64)&m)>0){if(m.type==KEY&&m.bytes==sizeof(KeyEv)){auto*k=(KeyEv*)m.payload;key((char)k->codepoint);}else if(m.type==POINTER&&m.bytes==sizeof(PtrEv)){auto*p=(PtrEv*)m.payload;if(p->flags&1){if(p->x>=30&&p->x<470){if(p->y>=100&&p->y<142)field=0;else if(p->y>=172&&p->y<214)field=1;else if(p->y>=244&&p->y<286)field=2;else if(p->y>=316&&p->y<358)field=3;else if(p->y>=384&&p->y<426)save();dirty=true;}}}else if(m.type==CLOSE)sc(0,0);}if(dirty)draw();sc(SYS_YIELD);}}
